package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

type Role int

const (
	RoleViewer Role = iota
	RoleEditor
	RoleAdmin
)

type User struct {
	ID   string
	Name string
	Role Role
}

type ImageJob struct {
	ID        string
	OwnerID   string
	InputPath string
	Status    string
	CreatedAt time.Time
}

type ImagePipeline struct {
	mu       sync.RWMutex
	jobs     map[string]*ImageJob
	users    map[string]*User
	basePath string
}

func NewImagePipeline(basePath string) *ImagePipeline {
	os.MkdirAll(basePath, 0750)
	return &ImagePipeline{
		jobs:     make(map[string]*ImageJob),
		users:    make(map[string]*User),
		basePath: basePath,
	}
}

func (p *ImagePipeline) RegisterUser(id, name string, role Role) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.users[id] = &User{ID: id, Name: name, Role: role}
}

func generateID() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func (p *ImagePipeline) validatePath(inputPath string) error {
	cleaned := filepath.Clean(inputPath)
	if strings.Contains(cleaned, "..") {
		return fmt.Errorf("path traversal detected")
	}
	fullPath := filepath.Join(p.basePath, cleaned)
	if !strings.HasPrefix(fullPath, p.basePath) {
		return fmt.Errorf("path escapes base directory")
	}
	return nil
}

// checkAccess verifies the user has permission to perform the action
func (p *ImagePipeline) checkAccess(userID string, job *ImageJob, action string) bool {
	p.mu.RLock()
	user, exists := p.users[userID]
	p.mu.RUnlock()
	if !exists {
		return false
	}
	switch action {
	case "read":
		return user.Role >= RoleViewer
	case "write":
		return user.Role >= RoleEditor && job.OwnerID == userID
	case "delete":
		return user.Role >= RoleAdmin || job.OwnerID == userID
	case "process":
		return user.Role >= RoleEditor && job.OwnerID == userID
	}
	return false
}

// SubmitJob creates a new image processing job
func (p *ImagePipeline) SubmitJob(userID, imagePath string) (string, error) {
	if err := p.validatePath(imagePath); err != nil {
		return "", err
	}

	p.mu.RLock()
	user, exists := p.users[userID]
	p.mu.RUnlock()
	if !exists || user.Role < RoleEditor {
		return "", fmt.Errorf("access denied: insufficient role")
	}

	jobID := generateID()
	job := &ImageJob{
		ID:        jobID,
		OwnerID:   userID,
		InputPath: imagePath,
		Status:    "pending",
		CreatedAt: time.Now(),
	}

	p.mu.Lock()
	p.jobs[jobID] = job
	p.mu.Unlock()

	return jobID, nil
}

// ProcessJob performs the image transformation
func (p *ImagePipeline) ProcessJob(userID, jobID string) error {
	p.mu.RLock()
	job, exists := p.jobs[jobID]
	p.mu.RUnlock()
	if !exists {
		return fmt.Errorf("job not found")
	}

	if !p.checkAccess(userID, job, "process") {
		return fmt.Errorf("access denied")
	}

	// Validate the path is still safe before processing
	if err := p.validatePath(job.InputPath); err != nil {
		return err
	}

	// Resolve the full path for processing
	fullPath := filepath.Join(p.basePath, filepath.Clean(job.InputPath))

	// Verify file exists and get info (CHECK)
	info, err := os.Lstat(fullPath)
	if err != nil {
		return fmt.Errorf("file not accessible: %v", err)
	}

	// Reject symlinks for security
	if info.Mode()&os.ModeSymlink != 0 {
		return fmt.Errorf("symlinks not allowed")
	}

	if info.Size() > 50*1024*1024 {
		return fmt.Errorf("file too large")
	}

	// Mark as processing
	p.mu.Lock()
	job.Status = "processing"
	p.mu.Unlock()

	// Simulate processing delay (real pipeline would do image transforms)
	time.Sleep(100 * time.Millisecond)

	// Open and read the file for processing (USE)
	file, err := os.Open(fullPath)
	if err != nil {
		p.mu.Lock()
		job.Status = "failed"
		p.mu.Unlock()
		return fmt.Errorf("failed to open file: %v", err)
	}
	defer file.Close()

	outputPath := fullPath + ".processed"
	outFile, err := os.OpenFile(outputPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0640)
	if err != nil {
		p.mu.Lock()
		job.Status = "failed"
		p.mu.Unlock()
		return fmt.Errorf("failed to create output: %v", err)
	}
	defer outFile.Close()

	// Copy with simulated transformation
	_, err = io.Copy(outFile, file)
	if err != nil {
		p.mu.Lock()
		job.Status = "failed"
		p.mu.Unlock()
		return err
	}

	p.mu.Lock()
	job.Status = "completed"
	p.mu.Unlock()

	return nil
}

// UpdateJobPath allows an editor to change the input path of a pending job
func (p *ImagePipeline) UpdateJobPath(userID, jobID, newPath string) error {
	if err := p.validatePath(newPath); err != nil {
		return err
	}

	p.mu.RLock()
	job, exists := p.jobs[jobID]
	p.mu.RUnlock()
	if !exists {
		return fmt.Errorf("job not found")
	}

	if !p.checkAccess(userID, job, "write") {
		return fmt.Errorf("access denied")
	}

	p.mu.Lock()
	if job.Status == "pending" || job.Status == "processing" {
		job.InputPath = newPath
	}
	p.mu.Unlock()

	return nil
}

func main() {
	pipeline := NewImagePipeline("/var/images")
	pipeline.RegisterUser("admin1", "Admin", RoleAdmin)
	pipeline.RegisterUser("editor1", "Editor", RoleEditor)
	pipeline.RegisterUser("viewer1", "Viewer", RoleViewer)

	http.HandleFunc("/submit", func(w http.ResponseWriter, r *http.Request) {
		userID := r.Header.Get("X-User-ID")
		imagePath := r.FormValue("path")
		jobID, err := pipeline.SubmitJob(userID, imagePath)
		if err != nil {
			http.Error(w, err.Error(), http.StatusForbidden)
			return
		}
		fmt.Fprintf(w, "Job created: %s", jobID)
	})

	http.HandleFunc("/process", func(w http.ResponseWriter, r *http.Request) {
		userID := r.Header.Get("X-User-ID")
		jobID := r.FormValue("job_id")
		if err := pipeline.ProcessJob(userID, jobID); err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		fmt.Fprintf(w, "Job processed successfully")
	})

	http.HandleFunc("/update", func(w http.ResponseWriter, r *http.Request) {
		userID := r.Header.Get("X-User-ID")
		jobID := r.FormValue("job_id")
		newPath := r.FormValue("new_path")
		if err := pipeline.UpdateJobPath(userID, jobID, newPath); err != nil {
			http.Error(w, err.Error(), http.StatusForbidden)
			return
		}
		fmt.Fprintf(w, "Job path updated")
	})

	http.ListenAndServe(":8080", nil)
}
